exercises.solutionCode:
#define DEV_MAJOR_BITS 12u
#define DEV_MINOR_BITS 20u

long long my_mkdev(unsigned int major, unsigned int minor)
{
    const unsigned int major_max = 1u << DEV_MAJOR_BITS; /* 2^12 */
    const unsigned int minor_max = 1u << DEV_MINOR_BITS; /* 2^20 */

    if (major >= major_max || minor >= minor_max) {
        return -1;
    }
    return (long long)((major << DEV_MINOR_BITS) | minor);
}

int my_major(long long dev)
{
    const unsigned int major_mask = (1u << DEV_MAJOR_BITS) - 1u;

    if (dev < 0) {
        return -1;
    }
    return (int)(((unsigned long long)dev >> DEV_MINOR_BITS) & major_mask);
}
